{"command":"kubectl exec -n default tc67 -- bash -c '
echo "== /app ==";
curl -s -o /dev/null -w "HTTP %{http_code}\n" -H "Host: app.example.com" http://10.96.122.8/app;
curl -s -o /app-out.html -w "== /app body ==" -H "Host: app.example.com" http://10.96.122.8/app | head -4;
echo "=== /app/sub ===";
curl -s -o /dev/null -w "HTTP %{http_code}\n" -H "Host: app.example.com" http://10.96.122.8/app/some/deep/path;
echo "=== bad host ===";
curl -s -o /dev/null -w "HTTP %{http_code}\n" -H "Host: other.example.com" http://10.96.122.8/app;
echo "=== wrong path ===";
curl -s -o /dev/null -w "HTTP %{http_code}\n" -H "Host: app.example.com" http://10.96.122.8/notapp';
cat /app-out.html | head -4"}

{"command":"kubectl exec -n default app-bb695fb5-mmdxl -- bash -c '
echo "--- nginx /app ---";
curl -s -o /dev/null -w "HTTP %{http_code}\n" http://127.0.0.1/app;
curl -s -o /dev/null -w "HTTP %{http_code}\n" -H "Host: app.example.com" http://127.0.0.1/app;
echo "--- /app content ---"; curl -s http://127.0.0.1/app | head -4;
echo "--- /app/sub ---"; curl -s -o /dev/null -w "HTTP %{http_code}\n" http://127.0.0.1/app/foo;
echo "--- /otherhost ---"; curl -s -o /dev/null -w "HTTP %{http_code}\n" -H "Host: other.host" http://127.0.0.1/app;
'; echo "--- traefik container log tail ---"; kubectl logs -n traefik deploy/traefik --tail=30 | tail -20"}

{"command":"for i in $(seq 1 20); do
  R=$(kubectl get routers -n traefik -o jsonpath='{range .items[*]}{.metadata.name}{"\t"}{.spec.rule}{"\t"}{.spec.backend}{"\t"}{.spec.priority}{"\t"}{.metadata.namespace}{"\n"}{end}' 2>/dev/null); echo "rc$i: $R";
  [ -n "$R" ] && break;
  sleep 5
done
echo "=== routerdetails ==="; kubectl get routers -n traefik -o jsonpath='{.items[0]}{"\n"}'; echo "=== routes ==="; kubectl get routes -n traefik -o jsonpath='{.items[0]}{"\n"}'; echo "=== ingressroute ==="; kubectl get ingressroute -n default -o jsonpath='{range .items[*]}{.metadata.name}{"\n"}{end}' 2>/dev/null"}

